INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2022-04-01-canada-federal-b2g-mandate', '2022-04-01', '2022-04', 'Since April 2022, all suppliers to the Canadian federal government must invoice electronically through the SAP Ariba platform, in Peppol BIS or UBL-XML format — but Canada still has no domestic B2B e-invoicing mandate of any kind.', '<h3>🇨🇦 Federal B2G e-invoicing mandatory via SAP Ariba — still the only hard requirement</h3>
<p>Since April 2022, Public Services and Procurement Canada (PSPC) has required every supplier to the federal government to submit invoices electronically through the SAP Ariba platform, formatted as Peppol BIS or UBL-XML. This rollout was largely complete by mid-2022, and it remains, even now, the one genuine e-invoicing mandate anywhere in the Canadian market. The Canada Revenue Agency separately requires electronic invoices to be archived for a minimum of six years, with integrity and authenticity maintained throughout that retention period.</p>
<p>Outside federal procurement, the picture is genuinely different from most countries in this tracker: Canada has no domestic B2B e-invoicing mandate at all. The CRA currently accepts invoices in any readable format — paper, PDF, or EDI — provided they contain the required tax information, and Canadian businesses continue to rely heavily on PDF invoices and traditional EDI arrangements in day-to-day trade. This makes Canada one of the more conservative markets in this tracker on the B2B side specifically, even as its federal B2G requirement has been fully in force for several years.</p>
<p><strong>What this means for your team:</strong> if you supply the Canadian federal government, SAP Ariba connectivity in the correct format isn''t optional or new — it''s been the baseline requirement since 2022, so confirm it''s genuinely working rather than assuming it from years ago is still correctly configured. For domestic B2B trade, don''t look for a mandate that doesn''t exist yet — check your specific trading partners'' own contractual expectations instead, since nothing in Canadian tax law currently requires structured e-invoicing outside the federal government relationship.</p>', 'https://www.canada.ca/en/public-services-procurement.html', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2022-04-01-canada-federal-b2g-mandate', id FROM countries WHERE name_en = 'Canada';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2022-04-01-canada-federal-b2g-mandate', 'en', 'Federal B2G e-invoicing mandatory via SAP Ariba — still the only hard requirement', 'Since April 2022, all suppliers to the Canadian federal government must invoice electronically through the SAP Ariba platform, in Peppol BIS or UBL-XML format — but Canada still has no domestic B2B e-invoicing mandate of any kind.', '<h3>🇨🇦 Federal B2G e-invoicing mandatory via SAP Ariba — still the only hard requirement</h3>
<p>Since April 2022, Public Services and Procurement Canada (PSPC) has required every supplier to the federal government to submit invoices electronically through the SAP Ariba platform, formatted as Peppol BIS or UBL-XML. This rollout was largely complete by mid-2022, and it remains, even now, the one genuine e-invoicing mandate anywhere in the Canadian market. The Canada Revenue Agency separately requires electronic invoices to be archived for a minimum of six years, with integrity and authenticity maintained throughout that retention period.</p>
<p>Outside federal procurement, the picture is genuinely different from most countries in this tracker: Canada has no domestic B2B e-invoicing mandate at all. The CRA currently accepts invoices in any readable format — paper, PDF, or EDI — provided they contain the required tax information, and Canadian businesses continue to rely heavily on PDF invoices and traditional EDI arrangements in day-to-day trade. This makes Canada one of the more conservative markets in this tracker on the B2B side specifically, even as its federal B2G requirement has been fully in force for several years.</p>
<p><strong>What this means for your team:</strong> if you supply the Canadian federal government, SAP Ariba connectivity in the correct format isn''t optional or new — it''s been the baseline requirement since 2022, so confirm it''s genuinely working rather than assuming it from years ago is still correctly configured. For domestic B2B trade, don''t look for a mandate that doesn''t exist yet — check your specific trading partners'' own contractual expectations instead, since nothing in Canadian tax law currently requires structured e-invoicing outside the federal government relationship.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-04-22-canada-dbnalliance-momentum', '2026-04-22', '2026-04', 'DBNAlliance — the North American counterpart to Peppol — is building genuine momentum through 2026, with regular member onboarding sessions and a dedicated E-Invoicing Conference in New York, offering Canadian businesses a voluntary structured exchange option even though no domestic mandate requires one.', '<h3>🇨🇦 DBNAlliance gains real momentum as the voluntary North American e-invoicing option</h3>
<p>With no domestic B2B mandate in either Canada or the United States, the Digital Business Networks Alliance (DBNAlliance) has emerged as North America''s genuine, if entirely voluntary, answer to Europe''s Peppol network — a four-corner exchange model open to businesses on both sides of the border. Formed by Business Payments Coalition market pilot participants, DBNAlliance is building real, visible momentum through 2026: regular onboarding sessions walk new members through the implementation process step by step, and a dedicated E-Invoicing Conference in New York this April brought together procurement, finance, tax, and IT leaders specifically to discuss compliance, interoperability, and where e-invoicing in North America is heading next.</p>
<p>For Canadian businesses specifically, DBNAlliance offers a genuine structured exchange option using the OASIS UBL format — the same underlying standard used by several other countries in this tracker — without waiting for any federal mandate that doesn''t yet exist. Registration works through a DBNAlliance Access Point, an online platform handling both sending and receiving of compliant e-invoices on a business''s behalf, in a model deliberately similar to how Peppol access points function in Europe.</p>
<p><strong>What this means for your team:</strong> if your business trades heavily with US counterparties, or simply wants genuine structured invoicing efficiency without waiting for a Canadian mandate that may be years away, DBNAlliance is worth evaluating now as a voluntary option rather than treating structured e-invoicing as something only relevant once a domestic law requires it. Given the momentum building through 2026''s conferences and onboarding sessions, this network is genuinely maturing, not merely a paper initiative.</p>', 'https://www.canada.ca/en/public-services-procurement.html', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-04-22-canada-dbnalliance-momentum', id FROM countries WHERE name_en = 'Canada';
